mapper.insert:
INSERT	/* SQL_ID: ci.sc.cmmn.file.fileMapper.insert.insertFile -- 첨부파일 등록*/ 
INTO USCM.TBCM_ARCH_FILE_L 	/* 첨부파일내역 */
(
 ATCH_FILE_GROUP_NO
 ,ATCH_FILE_SN				/* 첨부파일일련번호 */ 
 ,ATCH_FILE_NM				/* 첨부파일명 */ 
 ,ORGNL_FILE_NM				/* 원본파일명 */ 
 ,ATCH_FILE_PATH_NM			/* 첨부파일경로명 */ 
 ,EXTN_NM					/* 확장자명 */ 
 ,FILE_SZ					/* 파일크기 */ 
 ,USE_YN					/* 사용여부 */ 
 ,ATCH_FILE_CN				/* 첨부파일내용 */ 
 ,FRST_CRT_PRCR_ID			/* 최초생성처리자아이디 */ 
 ,FRST_CRT_DT				/* 최초생성일시 */ 
 ,LAST_CHG_PRCR_ID			/* 최종변경처리자아이디 */ 
 ,LAST_CHG_DT				/* 최종변경일시 */ 
) VALUES (
  #{atchFileGroupNo}
  ,#{atchFileSn}
  ,#{atchFileNm}
  ,#{orgnlFileNm}
  ,#{atchFilePathNm}
  ,#{extnNm}
  ,#{fileSz}
  ,#{useYn}
  ,#{atchFileCn}
  ,#{frstCrtPrcrId}
  ,TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
  ,#{lastChgPrcrId}
  ,TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
)

mapper.select:
SELECT /* SQL_ID: ci.sc.cmmn.file.fileMapper.select.selectFileInfo -- 파일 다운로드 */ ATCH_FILE_GROUP_NO ,ATCH_FILE_SN /* 첨부파일일련번호 */ ,ATCH_FILE_NM /* 첨부파일명 */ ,ORGNL_FILE_NM /* 원본파일명 */ ,ATCH_FILE_PATH_NM /* 첨부파일경로명 */ ,EXTN_NM /* 확장자명 */ ,FILE_SZ /* 파일크기 */ ,USE_YN /* 사용여부 */ ,ATCH_FILE_CN /* 첨부파일내용 */ ,FRST_CRT_PRCR_ID /* 최초생성처리자아이디 */ ,TO_CHAR( TO_TIMESTAMP(FRST_CRT_DT, 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD HH24:MI:SS' ) AS FRST_CRT_DT /* 최초생성일시 */ ,LAST_CHG_PRCR_ID /* 최종변경처리자아이디 */ ,TO_CHAR( TO_TIMESTAMP(LAST_CHG_DT, 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD HH24:MI:SS' ) AS LAST_CHG_DT /* 최종변경일시 */ FROM USCM.TBCM_ARCH_FILE_L /* 첨부파일내역 */ WHERE ATCH_FILE_GROUP_NO = #{atchFileGroupNo}
AND ATCH_FILE_SN = #{atchFileSn} /* 첨부파일일련번호 */
AND USE_YN = 'Y' /* 사용여부 */ LIMIT 1

choose.when:
SELECT COALESCE(MAX(ATCH_FILE_SN), 0)
FROM USCM.TBCM_ARCH_FILE_L
WHERE ATCH_FILE_GROUP_NO = #{atchFileGroupNo}
